/**
 * Shared helpers for tests that run the generator over the committed
 * rustdoc JSON fixtures (tests/fixtures/<crate>.v57.json / .v60.json,
 * regenerated by scripts/gen-fixtures.sh).
 */

import { readFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import {
  RustdocGenerator,
  type GeneratorOptions,
  type GeneratedFile,
} from "../../src/generator.js";
import { validateRustdocJson } from "../../src/validation.js";
import type { RustdocCrate } from "../../src/types.js";

const fixturesDir = join(dirname(fileURLToPath(import.meta.url)), "..", "fixtures");

/** Both rustdoc JSON format versions the fixtures are generated in. */
export const FORMATS = ["v57", "v60"] as const;
export type FixtureFormat = (typeof FORMATS)[number];

export function loadCrate(name: string): RustdocCrate {
  const data: unknown = JSON.parse(readFileSync(join(fixturesDir, name), "utf-8"));
  return validateRustdocJson(data).crate;
}

export function generateFixture(
  name: string,
  format: FixtureFormat,
  options: Partial<GeneratorOptions> = {}
): GeneratedFile[] {
  const crate = loadCrate(`${name}.${format}.json`);
  return new RustdocGenerator(crate, {
    output: "/tmp/rtf-test",
    baseUrl: "/docs/api",
    ...options,
  }).generate();
}

export function fileMap(files: GeneratedFile[]): Map<string, string> {
  return new Map(files.map((f) => [f.path, f.content]));
}

export function metaPages(files: Map<string, string>, path: string): unknown[] {
  const raw = files.get(path);
  if (raw === undefined) throw new Error(`no ${path}`);
  return (JSON.parse(raw) as { pages: unknown[] }).pages;
}
